import{_ as a,o,c as n,a2 as t}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Macro-Introduction.md","filePath":"manual-en/Macro-Introduction.md","lastUpdated":1785684581000}'),r={name:"manual-en/Macro-Introduction.md"};function i(c,e,s,d,l,m){return o(),n("div",null,[...e[0]||(e[0]=[t(`<h4 id="_14-2-2-introduction" tabindex="-1">14.2.2 Introduction <a class="header-anchor" href="#_14-2-2-introduction" aria-label="Permalink to &quot;14.2.2 Introduction&quot;">​</a></h4><p>The DEFINE command creates a <em>macro</em> , which is a name for a fragment of PSPP syntax called the macro’s <em>body</em>. Following the DEFINE command, syntax may <em>call</em> the macro by name any number of times. Each call substitutes, or <em>expands</em> , the macro’s body in place of the call, as if the body had been written in its place.</p><p>The following syntax defines a macro named <code>!vars</code> that expands to the variable names <code>v1 v2 v3</code>. The macro’s name begins with ‘!’, which is optional for macro names. The <code>()</code> following the macro name are required:</p><pre><code>DEFINE !vars()
v1 v2 v3
!ENDDEFINE.
</code></pre><p>Here are two ways that <code>!vars</code> might be called given the preceding definition:</p><pre><code>DESCRIPTIVES !vars.
FREQUENCIES /VARIABLES=!vars.
</code></pre><p>With macro expansion, the above calls are equivalent to the following:</p><pre><code>DESCRIPTIVES v1 v2 v3.
FREQUENCIES /VARIABLES=v1 v2 v3.
</code></pre><p>The <code>!vars</code> macro expands to a fixed body. Macros may have more sophisticated contents:</p><ul><li>Macro <em>arguments</em> that are substituted into the body whenever they are named. The values of a macro’s arguments are specified each time it is called. See <a href="./Macro-Arguments">Macro Arguments</a>.</li><li>Macro <em>functions</em> , expanded when the macro is called. See <a href="./Macro-Functions">Macro Functions</a>.</li><li><code>!IF</code> constructs, for conditional expansion. See <a href="./Macro-Conditional-Expansion">Macro Conditional Expansion</a>.</li><li>Two forms of <code>!DO</code> construct, for looping over a numerical range or a collection of tokens. See <a href="./Macro-Loops">Macro Loops</a>.</li><li><code>!LET</code> constructs, for assigning to macro variables. See <a href="./Macro-Variable-Assignment">Macro Variable Assignment</a>.</li></ul><p>Many identifiers associated with macros begin with ‘!’, a character not normally allowed in identifiers. These identifiers are reserved only for use with macros, which helps keep them from being confused with other kinds of identifiers.</p><p>The following sections provide more details on macro syntax and semantics.</p>`,12)])])}const f=a(r,[["render",i]]);export{p as __pageData,f as default};
